node --input-type=module <<'NODE'
import { registerHooks } from 'node:module';
import { existsSync } from 'node:fs';
registerHooks({
  resolve(specifier, context, next) {
    if (context.parentURL?.includes('/src/') && specifier.startsWith('.') && specifier.endsWith('.js')) {
      const source = new URL(specifier.replace(/\.js$/, '.ts'), context.parentURL);
      if (existsSync(source)) return next(source.href, context);
    }
    return next(specifier, context);
  },
});
const { loadVendorFile } = await import('./tools/node-vendor.mjs');
for (const f of ['compiler/typed/tape.js','compiler/typed/typed-wasm.js','bench/host/rv32-interp.js','compiler/typed/typed-rv32.js','compiler/typed/typed-rv32-inline.js','compiler/typed/typed-rv32-loops.js','compiler/typed/typed-rv32-kernel.js']) loadVendorFile(f);
const { setVendor } = await import('./src/typed/vendor.ts');
setVendor({typedTape: globalThis.typedTape, typedWasm: globalThis.typedWasm, typedRv32Interp: globalThis.typedRv32Interp, typedRv32: globalThis.typedRv32});
const { Program } = await import('./src/typed/program.ts');
const { sha256 } = await import('./src/framework/core/data.ts');
const B = await import('./src/typed/backend/index.ts');
const source = `function shifted(x: i32, n: i32): i32 { return (x >>> n) | (x << (32 - n)); }
function probe(buf: buffer, out: buffer): i32 {
  const a = new Int32Array(64);
  for (let i = 0; i < 3; i = i + 1) {
    a[i] = shifted(0x80000000 + buf.charCodeAt(i), 1);
  }
  out.setCharCodeAt(0, (a[2] >>> 24) & 255);
  return a[2];
}`;
const inputs = { shifted: { x: -2147483648, n: 1 }, probe: {buf: {cells:[255,0,2]}, out:{cells:[0]}} };
for (const options of [{}, {ingest:{tape:true, spans:true}}]) {
  const p = new Program('probe', source, {inputs, ...options});
  console.log('ingest', JSON.stringify(options), p.status, p.error);
  if (p.status !== 'ok') continue;
  console.log('r0', JSON.stringify(p.exec('probe', [[255,0,2],[0]], {limit:20000})));
  try {
    const r = globalThis.typedRv32.compile(source, [], undefined);
    const image = B.imageFromCode('probe', r.image, r.entries);
    console.log('reference', JSON.stringify(p.check({count:1, against:(fn,k)=>B.runImage(image,fn,k.args,k.memory)})));
    console.log('speed', (await p.pipeline('speed')).map?.(s=>[s.pass,s.check,s.rejected]) ?? 'ran');
    const own = B.lowerToImage(p.head, {coalesce:true, homes:true, chains:true}).image;
    console.log('speed-image', JSON.stringify(p.check({count:1,against:(fn,k)=>B.runImage(own,fn,k.args,k.memory)})));
  } catch(e) { console.log('probe failure', e.stack); }
}
console.log('framework SHA-256', sha256('abc'));
NODE

node --experimental-transform-types --input-type=module <<'NODE'
import { registerHooks } from 'node:module';
import { existsSync } from 'node:fs';
registerHooks({resolve(s,c,n) {
 if(c.parentURL?.includes('/src/') && s.startsWith('.') && s.endsWith('.js')) {
  const t=new URL(s.replace(/\.js$/,'.ts'),c.parentURL); if(existsSync(t))return n(t.href,c);
 }
 return n(s,c);
}});
const {loadVendorFile}=await import('./tools/node-vendor.mjs');
for(const f of ['compiler/typed/tape.js','compiler/typed/typed-wasm.js','bench/host/rv32-interp.js',...['','-inline','-loops','-kernel'].map(x=>'compiler/typed/typed-rv32'+x+'.js')])loadVendorFile(f);
const {setVendor}=await import('./src/typed/vendor.ts');
setVendor({typedTape:globalThis.typedTape,typedWasm:globalThis.typedWasm,typedRv32Interp:globalThis.typedRv32Interp,typedRv32:globalThis.typedRv32});
const {Program}=await import('./src/typed/program.ts');
const {sha256}=await import('./src/framework/core/data.ts');
const B=await import('./src/typed/backend/index.ts');
const src=`function shift(x: i32, n: i32): i32 { return (x >>> n) | (x << (32 - n)); }
function probe(buf: buffer, out: buffer): i32 {
 const a = new Int32Array(64);
 for (let i = 0; i < 3; i = i + 1) { a[i] = shift(0x80000000 + buf.charCodeAt(i), 1); }
 out.setCharCodeAt(0, (a[2] >>> 24) & 255);
 return a[2];
}`;
const inputs={shift:{x:-2147483648,n:1},probe:{buf:{cells:[255,0,2]},out:{cells:[0]}}};
for(const options of [{},{ingest:{tape:true,spans:true}}]) {
 const p=new Program('probe',src,{inputs,...options});
 console.log('ingest',JSON.stringify(options),p.status,p.error);
 if(p.status!=='ok')continue;
 console.log('r0',JSON.stringify(p.exec('probe',[[255,0,2],[0]],{limit:20000})));
 try {
  const r=globalThis.typedRv32.compile(src,[],undefined);
  const image=B.imageFromCode('probe',r.image,r.entries);
  const check=img=>p.check({count:1,against:(fn,k)=>B.runImage(img,fn,k.args,k.memory)}).fns.map(x=>[x.fn,x.status,x.agree,x.bothTrap,x.inconclusive]);
  console.log('reference',JSON.stringify(check(image)));
  console.log('speed',JSON.stringify(await p.pipeline('speed')).slice(0,260));
  const own=B.lowerToImage(p.head,{coalesce:true,homes:true,chains:true}).image;
  console.log('speed-image',JSON.stringify(check(own)));
 } catch(e){console.log('probe failure',e.stack);}
}
console.log('framework SHA-256',sha256('abc'));
