node --input-type=module <<'NODE'
import { createHash, createCipheriv } from 'node:crypto';
for (const message of ['', 'abc', 'abcdbcdecdefdefgefghfghighijhijkijkljklmklmnlmnomnopnopq']) {
  console.log(message.length, createHash('sha256').update(message).digest('hex'));
}
const key = Buffer.from(Array.from({length: 32}, (_, i) => i));
const iv = Buffer.from('01000000000000090000004a00000000', 'hex');
const cipher = createCipheriv('chacha20', key, iv);
console.log('ChaCha20', Buffer.concat([cipher.update(Buffer.alloc(64)), cipher.final()]).toString('hex'));
