node --experimental-transform-types --input-type=module <<'NODE'
import { registerHooks } from 'node:module';
import { existsSync } from 'node:fs';
registerHooks({resolve(s,c,n) {
 if(c.parentURL?.includes('/src/') && s.startsWith('.') && s.endsWith('.js')) {
  const t=new URL(s.replace(/\.js$/,'.ts'),c.parentURL); if(existsSync(t))return n(t.href,c);
 }
 return n(s,c);
}});
const {loadVendorFile}=await import('./tools/node-vendor.mjs');
for(const f of ['compiler/typed/tape.js','compiler/typed/typed-wasm.js','bench/host/rv32-interp.js',...['','-inline','-loops','-kernel'].map(x=>'compiler/typed/typed-rv32'+x+'.js')])loadVendorFile(f);
const {setVendor}=await import('./src/typed/vendor.ts');
setVendor({typedTape:globalThis.typedTape,typedWasm:globalThis.typedWasm,typedRv32Interp:globalThis.typedRv32Interp,typedRv32:globalThis.typedRv32});
const {Program}=await import('./src/typed/program.ts');
const {sha256}=await import('./src/framework/core/data.ts');
const B=await import('./src/typed/backend/index.ts');

const source = `function writeWord(out: buffer, offset: i32, word: i32): i32 {
  for (let j = 0; j < 4; j = j + 1) {
    out.setCharCodeAt(offset + j, (word >>> (8 * j)) & 255);
  }
  return 0;
}
function arrays(b: buffer, out: buffer): i32 {
  const pad = new Int32Array(128);
  const h = new Int32Array(8);
  const w = new Int32Array(64);
  for (let i = 0; i < b.length; i = i + 1) { pad[i] = b.charCodeAt(i); }
  w[0] = (pad[0] << 24) | (pad[1] << 16) | (pad[2] << 8) | pad[3];
  h[7] = (w[0] ^ -1) + 0x80000000;
  writeWord(out, 0, h[7]);
  return 0;
}`;
const p=new Program('arrays',source,{ingest:{tape:true},inputs:{writeWord:{out:{buffer:[4,4],cell:[0,65535]},offset:0,word:[-2147483648,2147483647]},arrays:{b:{buffer:[0,119],cell:[0,255]},out:{buffer:[4,4],cell:[0,65535]}}}});
if(p.status!=='ok') throw Error(JSON.stringify(p.error));
const result=p.exec('arrays',[[128,0,0,0],[65535,65535,65535,65535]],{limit:20000});
console.log(JSON.stringify(result));
if(result.trap||result.result!==0||result.buffers[1].cells.join()!=='255,255,255,255') throw Error('unexpected result');
const ref=globalThis.typedRv32.compile(source,[],undefined);
for(const image of [B.imageFromCode('arrays',ref.image,ref.entries),B.lowerToImage(p.head).image]){
 const rows=p.check({count:10,against:(fn,k)=>B.runImage(image,fn,k.args,k.memory)}).fns;
 console.log(JSON.stringify(rows));
 if(rows.some(r=>r.agree!==10||r.bothTrap||r.inconclusive))throw Error('unexpected comparison result');
}
