ticket=ttmp/2026/11/26/IRWB-013--sha-256-and-chacha20
git status --short --untracked-files=all
sed -n '1,47p' "$ticket"/design-doc/*.md
cat "$ticket"/tasks.md
node --input-type=module - "$ticket"/design-doc/*.md <<'NODE'
import { readFileSync } from 'node:fs';
import assert from 'node:assert/strict';
const doc = readFileSync(process.argv[2], 'utf8');
const meta = JSON.parse(doc.match(/```json
([\s\S]*?)
```/)[1]);
assert.deepEqual(Object.keys(meta.inputs).sort(), ['chacha20','readLE','readPair','rotl','rotr','sha256','writeLE']);
assert.equal(meta.ingest.tape, true);
assert.equal(meta.pipeline, 'speed');
const budgets = [30*128+20*32+30*96+45*128+20*32+512, 80*(12+4*6)+2000];
assert(budgets.every(n => n < 16000));
console.log('Project JSON parsed; all seven functions have input specs; planning budgets', budgets);
NODE
